package com.yuegang.zhihui.ai.application;import com.yuegang.zhihui.ai.api.*;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.search.api.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;
public final class ChatService{private static final String SYSTEM="你是跨境智汇企业客服。只能依据提供的已审核资料回答；必须标注引用；资料不足时明确拒答；不得生成SQL、修改订单、调整余额或发布知识。";private final RetrievalGateway retrieval;private final ModelGateway model;private final JdbcTemplate jdbc;private final TransactionTemplate tx;public ChatService(RetrievalGateway r,ModelGateway m,DataSource d){retrieval=r;model=m;jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public ChatResponse chat(long user,ChatRequest request){List<SearchHit>hits=retrieval.search(request.message(),request.category(),8);boolean professional=request.message().matches(".*(政策|法规|通关|关税|溯源|原产地).*?");if(hits.isEmpty()&&professional)return save(user,request,"当前已审核知识库中没有足够依据，无法可靠回答该专业问题。",List.of(),true,"INSUFFICIENT_EVIDENCE");String context=hits.stream().map(h->"["+h.documentId()+"/"+h.chunkId()+"] "+h.title()+"\n"+h.excerpt()).reduce("",(a,b)->a+"\n"+b);String answer=model.answer(SYSTEM,"资料：\n"+context+"\n\n问题："+request.message());List<CitationView>citations=hits.stream().map(h->new CitationView("KNOWLEDGE",h.chunkId(),h.title(),h.excerpt(),null)).toList();return save(user,request,answer,citations,false,null);}private ChatResponse save(long user,ChatRequest r,String answer,List<CitationView>citations,boolean refused,String reason){return tx.execute(s->{long conversation=r.conversationId()==null||r.conversationId().isBlank()?next():Long.parseLong(r.conversationId());jdbc.update("INSERT INTO ai_conversation(id,user_id,title) VALUES(?,?,?) ON DUPLICATE KEY UPDATE updated_at=NOW(6)",conversation,user,r.message().substring(0,Math.min(100,r.message().length())));jdbc.update("INSERT INTO ai_message(id,conversation_id,role,content) VALUES(?,?,'USER',?)",next(),conversation,r.message());long message=next();jdbc.update("INSERT INTO ai_message(id,conversation_id,role,content,refused,model_name) VALUES(?,?,'ASSISTANT',?,?,?)",message,conversation,answer,refused,"doubao");int i=0;for(var c:citations)jdbc.update("INSERT INTO ai_citation(message_id,sequence_no,source_type,source_id,title,excerpt,url) VALUES(?,?,?,?,?,?,?)",message,i++,c.sourceType(),c.sourceId(),c.title(),c.excerpt(),c.url());return new ChatResponse(Long.toString(conversation),Long.toString(message),answer,citations,refused,reason);});}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
